-- answer has a student explanation (shown after submitting). Made available for the pilot: the teacher reviews the
-- content and allocates it to the named pilot student. Replaces v0.1.0 in place only if v0.1.0 is unchanged, was never
-- allocated or content-reviewed, and was never released. Nothing is released here.
do $upgrade$ begin
 update private.ielts_learning_tasks set version='0.2.0', title='Lesson 6 step 1 of 6: What is the question asking for?', instructions='Read LEARN FIRST and the worked example. Then, for each question phrase, choose the kind of information it asks for. Do not read the article yet.', success_description='Find the kind word first (account, example, caution, justification, option, or a word that means the same). The topic words are not the answer.', questions='[{"id": "q1", "prompt": "Phrase: \"mention of an option suited to buildings unable to carry a planted roof\". What kind of information is it?", "accepted_answers": ["E"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q2", "prompt": "Phrase: \"an account of how conditions after dark may weaken people''s capacity to cope with heat\". What kind of information is it?", "accepted_answers": ["A"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q3", "prompt": "Phrase: \"a warning that public money may be spent in the wrong places\". What kind of information is it?", "accepted_answers": ["C"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q4", "prompt": "Phrase: \"the reason councils give for charging owners of planted roofs lower fees\". What kind of information is it?", "accepted_answers": ["D"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q5", "prompt": "Phrase: \"an example of a way of coping with heat that makes the original problem worse\". What kind of information is it?", "accepted_answers": ["B"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}, {"id": "q6", "prompt": "Phrase: \"a description of how plants carry heat away from a roof\". What kind of information is it?", "accepted_answers": ["A"], "taxonomy_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "A  an account (how something happens)"}, {"value": "B", "label": "B  an example (one real case)"}, {"value": "C", "label": "C  a caution (a warning or doubt)"}, {"value": "D", "label": "D  a justification (the reason someone gives)"}, {"value": "E", "label": "E  an option (another choice or solution)"}]}]'::jsonb, content='{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 8, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "LEARN FIRST: name the KIND of information before you read\n\nIn matching-information questions you must find a paragraph that contains a certain KIND of information. The topic words are not enough. First find the word that names the kind.\n\nThe five kinds, and other words that mean the same:\nA  an account: explanation of how/why, description of how, process  -> a cause leading to an effect\nB  an example: instance, case, illustration  -> one real case of something more general\nC  a caution: warning, doubt, concern  -> something may be wrong, limited or risky\nD  a justification: the reason someone gives, argument for  -> why someone does something\nE  an option: alternative, solution, choice  -> another way of dealing with a problem\n\nWORKED EXAMPLE\nQuestion phrase: \"an explanation of how the soil layer keeps rooms cool\"\n1. Circle the kind word: \"an explanation of how\".\n2. Ask: is it a process, cause -> effect? Yes: soil layer -> heat moves slowly -> rooms stay cool.\n3. So the kind is A, an account. \"Soil\" and \"rooms\" are only the topic.\n\nNow do the same for the six phrases. Do not read the article yet.", "teacher_notes": "1 E, an option. The kind word is ''option''. ''Buildings unable to carry a planted roof'' is only the topic.\n2 A, an account. ''An account of how'' asks for a cause leading to an effect: warm nights -> people cope less well.\n3 C, a caution. ''Warning'' means the same as caution: something may go wrong.\n4 D, a justification. ''The reason someone gives'' for an action is a justification.\n5 B, an example. The question wants one real case (a way of coping that backfires).\n6 A, an account. ''A description of how'' something happens is a process: water evaporates from leaves and takes heat with it.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Select relevant information: identify the kind of information a matching-information question asks for before reading."}'::jsonb, review_record='{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.2.0"}'::jsonb, content_sha256='c74dd27f16ab777ad27ee0c41f83dd63a7ff71b27280ce128514e21d57a44092' where code='bh-ielts-targeted-reading-r28-v1' and content_sha256='bda53c9a973f647536db6eb5d548bbaa357933268c08e2ed8b76016982d590fe' and not exists(select 1 from private.ielts_learning_allocations a where a.task_code='bh-ielts-targeted-reading-r28-v1') and not exists(select 1 from private.ielts_learning_content_reviews r where r.task_code='bh-ielts-targeted-reading-r28-v1') and not exists(select 1 from private.ielts_learning_releases x where x.task_code='bh-ielts-targeted-reading-r28-v1');
 if not found then raise exception 'targeted_reading_06_upgrade_blocked: %', 'bh-ielts-targeted-reading-r28-v1'; end if;
 update private.ielts_learning_tasks set version='0.2.0', title='Lesson 6 step 2 of 6: Does this paragraph contain it?', instructions='Read LEARN FIRST and the worked examples. Then read only the paragraph named in each question and choose YES or NO.', success_description='Say YES only if the paragraph has the right KIND of information, about the right TOPIC, and you can copy the PROOF.', questions='[{"id": "q1", "prompt": "Paragraph C: does it contain a caution against drawing wide conclusions from evidence collected at one location?", "accepted_answers": ["YES"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q2", "prompt": "Paragraph A: does it contain an account of how conditions after dark may weaken people''s capacity to cope with heat?", "accepted_answers": ["NO"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q3", "prompt": "Paragraph F: does it contain the justification some local authorities give for offering financial help?", "accepted_answers": ["NO"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q4", "prompt": "Paragraph F: does it contain an option suited to buildings unable to carry a planted roof?", "accepted_answers": ["YES"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q5", "prompt": "Paragraph B: does it contain an account of how conditions after dark may weaken people''s capacity to cope with heat?", "accepted_answers": ["YES"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}, {"id": "q6", "prompt": "Paragraph D: does it contain an option suited to buildings unable to carry a planted roof?", "accepted_answers": ["NO"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "29a67bc9-2c34-42e6-9f5f-a8b592f7bb3b", "options": [{"value": "YES", "label": "YES, it contains this"}, {"value": "NO", "label": "NO, it does not"}]}]'::jsonb, content='{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "LEARN FIRST: check one paragraph in three questions\n\nRead only the paragraph named. Ask three questions:\n1. KIND: is the right kind of information there (an account, a caution, an option...)?\n2. TOPIC: is it about the right thing?\n3. PROOF: can I copy the words that show it?\nOnly if all three are YES is the answer YES.\n\nWORKED EXAMPLE 1\n\"Paragraph E: does it contain a complaint about who pays for green roofs?\"\nKind: a complaint. Topic: who pays. Proof: \"the financial burden falls entirely on them\".  -> YES\n\nWORKED EXAMPLE 2\n\"Paragraph C: does it contain a complaint about who pays for green roofs?\"\nC explains how green roofs cool buildings. There is no complaint and nothing about money.  -> NO\nThe topic (green roofs) is the same, but the KIND of information is missing.\n\n- - - - - - - - - - - - - - - - - - - -\n\nTHE PASSAGE: Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 YES. Kind: a caution. Proof: \"readings taken on a single rooftop reveal little about conditions in the surrounding district\". One location = a single rooftop.\n2 NO. A mentions the hours after dusk, but only describes temperatures. Nothing about people or coping: the topic matches, the kind does not.\n3 NO. F mentions grants, but it warns about where they go. It gives no reason for offering them. Echo word, wrong meaning.\n4 YES. Kind: an option (cool roofs). Proof: \"far cheaper on buildings whose structure cannot support soil\".\n5 YES. Proof: \"bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat\". Overnight = after dark; less able to withstand = weaker capacity to cope.\n6 NO. D says older buildings \"could not bear the additional load\", which names the problem but offers no option. Half an answer is a wrong answer.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Locate specific detail: decide whether one paragraph contains a given kind of information."}'::jsonb, review_record='{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.2.0"}'::jsonb, content_sha256='6bb73ed1caf02b82aaa4895675e397b547f9647b7177cee6a1e362901c9f4cb8' where code='bh-ielts-targeted-reading-r29-v1' and content_sha256='0d05ffe9059d10f752b4742553dfd32409871be93f9069816a9fe5ea80300470' and not exists(select 1 from private.ielts_learning_allocations a where a.task_code='bh-ielts-targeted-reading-r29-v1') and not exists(select 1 from private.ielts_learning_content_reviews r where r.task_code='bh-ielts-targeted-reading-r29-v1') and not exists(select 1 from private.ielts_learning_releases x where x.task_code='bh-ielts-targeted-reading-r29-v1');
 if not found then raise exception 'targeted_reading_06_upgrade_blocked: %', 'bh-ielts-targeted-reading-r29-v1'; end if;
 update private.ielts_learning_tasks set version='0.2.0', title='Lesson 6 step 3 of 6: Two paragraphs, one trap', instructions='Read LEARN FIRST and the worked example. Then choose the paragraph that contains the information. NB The same letter can be the answer more than once.', success_description='A word you recognise is a warning, not an answer. Choose the paragraph that has the meaning.', questions='[{"id": "q1", "prompt": "Which paragraph contains an account of how conditions after dark may weaken people''s capacity to cope with heat?", "accepted_answers": ["B"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}]}, {"id": "q2", "prompt": "Which paragraph contains an example of a way of coping with heat that makes the original problem worse?", "accepted_answers": ["B"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}]}, {"id": "q3", "prompt": "Which paragraph contains a caution against drawing wide conclusions from evidence collected at one location?", "accepted_answers": ["C"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}]}, {"id": "q4", "prompt": "Which paragraph contains a reference to the justification some local authorities give for offering financial help?", "accepted_answers": ["E"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "E", "label": "Paragraph E"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q5", "prompt": "Which paragraph contains mention of an option suited to buildings unable to carry a planted roof?", "accepted_answers": ["F"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "D", "label": "Paragraph D"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q6", "prompt": "Which paragraph contains a description of how plants carry heat away from a roof?", "accepted_answers": ["C"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}]}]'::jsonb, content='{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "LEARN FIRST: choose by meaning, not by a word you recognise\n\nIn each question, one paragraph shares a word or topic with the question (the trap). The other one has the meaning.\n\nWORKED EXAMPLE\nQuestion: \"a reason why some planted roofs do little for wildlife\". Paragraph C or D?\n1. Kind: a reason why. Topic: wildlife.\n2. C has the echo word \"vegetation\" and explains how plants cool roofs. No wildlife.  -> trap\n3. D: \"the thin mats of drought-tolerant sedum ... sustain only a fraction of the insect and bird life\". Insects and birds = wildlife; thin mats = the reason.  -> answer D\nRule: a word you recognise is a warning, not an answer.\nNB The same letter can be the answer more than once.\n\n- - - - - - - - - - - - - - - - - - - -\n\nTHE PASSAGE: Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 B: \"bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat\". Trap A: it mentions after dusk, but only temperatures.\n2 B: air conditioners'' waste heat \"intensifies the very problem they were bought to solve\". Trap A: it lists air-conditioning units only as a source of heat. B is used twice.\n3 C: \"readings taken on a single rooftop reveal little about conditions in the surrounding district\". Trap D: it limits the benefits but says nothing about evidence.\n4 E: \"reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers\". ''Reasoning that'' introduces the justification. Trap F: it mentions grants but criticises them.\n5 F: cool roofs \"are far cheaper on buildings whose structure cannot support soil\". Trap D: it names the problem buildings but gives no option.\n6 C: \"moisture drawn up through the roots evaporates from the leaves, carrying energy away with it\". Trap D: it mentions plants but is about wildlife and weight.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Locate specific detail when a nearby paragraph shares the topic or key words (matching information)."}'::jsonb, review_record='{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.2.0"}'::jsonb, content_sha256='37d6d965041b896ef22f3633b3b9a55a60b4930581759291aeae6347285a6da9' where code='bh-ielts-targeted-reading-r30-v1' and content_sha256='6b0ebab9824266c6dcc1c758ddfc60a0ab819a3adf19e05d1de96bd58eb22529' and not exists(select 1 from private.ielts_learning_allocations a where a.task_code='bh-ielts-targeted-reading-r30-v1') and not exists(select 1 from private.ielts_learning_content_reviews r where r.task_code='bh-ielts-targeted-reading-r30-v1') and not exists(select 1 from private.ielts_learning_releases x where x.task_code='bh-ielts-targeted-reading-r30-v1');
 if not found then raise exception 'targeted_reading_06_upgrade_blocked: %', 'bh-ielts-targeted-reading-r30-v1'; end if;
 update private.ielts_learning_tasks set version='0.2.0', title='Lesson 6 step 4 of 6: Predict, then find', instructions='Read LEARN FIRST and the worked example. Then complete each sentence with NO MORE THAN TWO WORDS from the passage. Copy the words exactly.', success_description='Predict the kind of word, find the same meaning in the passage, then reject the nearby word that looks right but is not.', questions='[{"id": "q1", "prompt": "During heatwaves, ________ rises as air conditioners run for longer.", "accepted_answers": ["electricity consumption"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q2", "prompt": "In a green roof, moisture ________ from the leaves and takes heat with it.", "accepted_answers": ["evaporates"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q3", "prompt": "Contrary to what might be expected, a city is warmest compared with the countryside not when the sun is strongest but well after ________.", "accepted_answers": ["dusk"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q4", "prompt": "Rooms directly under a green roof warm up less quickly because the growing layer provides ________.", "accepted_answers": ["insulation"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q5", "prompt": "On a very tall building, a planted roof may leave temperatures at ________ largely unchanged.", "accepted_answers": ["pavement level"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q6", "prompt": "Some councils charge owners of planted roofs lower ________ because these roofs hold back rainwater.", "accepted_answers": ["stormwater fees"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}]'::jsonb, content='{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "LEARN FIRST: predict the word, find it, reject the trap\n\nWrite NO MORE THAN TWO WORDS from the passage. Copy them exactly: the spelling must match.\n1. PREDICT: what kind of word fits the gap (noun, plural noun, verb, adjective, time word)?\n2. FIND: the sentence in the question uses different words. Find the same MEANING in the passage.\n3. REJECT: check the nearby word that looks right but is not.\n\nWORKED EXAMPLE\n\"On hot afternoons, planted roofs are much cooler than nearby ________ surfaces.\"\n1. Predict: a word that describes a kind of surface (one word, before \"surfaces\").\n2. Find: \"nearby\" = \"adjacent\" in paragraph C: \"dramatically cooler on hot afternoons than adjacent bitumen surfaces\".\n3. Reject: \"individual buildings\" is in the same sentence but is not a surface.\nAnswer: bitumen\n\nLook for contrast words too (not ... but, while, although, rather than). The wrong answer often sits on the other side of them.\n\n- - - - - - - - - - - - - - - - - - - -\n\nTHE PASSAGE: Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 electricity consumption (paragraph B): \"Electricity consumption climbs in parallel as air conditioners run for longer\". Rises = climbs. Trap: ''waste heat'' is what the machines expel, not what rises.\n2 evaporates (paragraph C): \"moisture drawn up through the roots evaporates from the leaves\". The gap needs a verb. Trap: ''drawn up'' happens in the roots, before the heat leaves.\n3 dusk (paragraph A): \"not in the early afternoon, when sunlight is most intense, but several hours after dusk\". ''Contrary to what might be expected'' = counter-intuitively. Trap: ''early afternoon'' is the time ruled out by ''not ... but''.\n4 insulation (paragraph C): \"The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below\". Growing layer = substrate. Trap: evapotranspiration cools the roof surface, not the rooms.\n5 pavement level (paragraph D): \"doing almost nothing for the air at pavement level\". Leave largely unchanged = do almost nothing for. Trap: ''upper floors'' are the part the roof does cool.\n6 stormwater fees (paragraph E): \"subsidies or reduced stormwater fees\". Charge lower = reduced. The gap needs something you are charged. Traps: ''sewers'' and ''drainage outlets'' are not charges.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Locate specific detail: complete sentences that paraphrase the passage, copying words exactly and rejecting nearby distractors."}'::jsonb, review_record='{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.2.0"}'::jsonb, content_sha256='2859c74adf3f5d47bc782191203c091f6d0018766fa8729963d0dc4d9995346c' where code='bh-ielts-targeted-reading-r31-v1' and content_sha256='76e7d005712f9eb0c3ffc2d2970544c8cbe9f51ec847b6ee23674d0aecfb83da' and not exists(select 1 from private.ielts_learning_allocations a where a.task_code='bh-ielts-targeted-reading-r31-v1') and not exists(select 1 from private.ielts_learning_content_reviews r where r.task_code='bh-ielts-targeted-reading-r31-v1') and not exists(select 1 from private.ielts_learning_releases x where x.task_code='bh-ielts-targeted-reading-r31-v1');
 if not found then raise exception 'targeted_reading_06_upgrade_blocked: %', 'bh-ielts-targeted-reading-r31-v1'; end if;
 update private.ielts_learning_tasks set version='0.2.0', title='Lesson 6 step 5 of 6: Who says what?', instructions='Read LEARN FIRST and the worked example. Then choose the group that holds or does each thing.', success_description='The group named next to a view is not always the group that holds it. Find who is saying it: note, caution, contend, argue, warn.', questions='[{"id": "q1", "prompt": "Paragraph D: who chooses the thin mats of drought-tolerant sedum?", "accepted_answers": ["B"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  ecologists"}, {"value": "B", "label": "B  developers"}, {"value": "C", "label": "C  engineers"}, {"value": "D", "label": "D  property owners"}]}, {"id": "q2", "prompt": "Paragraph D: who criticises the thin mats of sedum?", "accepted_answers": ["C"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  developers"}, {"value": "B", "label": "B  engineers"}, {"value": "C", "label": "C  ecologists"}, {"value": "D", "label": "D  urban planners"}]}, {"id": "q3", "prompt": "Paragraph E: who says that they pay while the public gains?", "accepted_answers": ["D"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  municipalities"}, {"value": "B", "label": "B  the wider public"}, {"value": "C", "label": "C  urban planners"}, {"value": "D", "label": "D  property owners"}]}, {"id": "q4", "prompt": "Paragraph E: who responds by offering subsidies?", "accepted_answers": ["A"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  municipalities"}, {"value": "B", "label": "B  property owners"}, {"value": "C", "label": "C  epidemiologists"}, {"value": "D", "label": "D  developers"}]}, {"id": "q5", "prompt": "Paragraph D: which word shows that the engineers hold a view?", "accepted_answers": ["B"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  caution"}, {"value": "B", "label": "B  note"}, {"value": "C", "label": "C  contend"}, {"value": "D", "label": "D  warn"}]}, {"id": "q6", "prompt": "Paragraph B: who argues that warm nights make people less able to cope with heat?", "accepted_answers": ["D"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  municipal authorities"}, {"value": "B", "label": "B  elderly residents"}, {"value": "C", "label": "C  engineers"}, {"value": "D", "label": "D  epidemiologists"}]}]'::jsonb, content='{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "LEARN FIRST: find who is SAYING it, not who is nearby\n\nSeveral groups are often named close together. The group named next to a view is not always the group that holds it.\n1. Circle every group of people in the paragraph.\n2. Find each group''s saying or doing word: note, caution, contend, argue, warn, regard, respond.\n3. Match the view to the group that says it.\n\nWORKED EXAMPLE\n\"Paragraph B: who now treats lowering temperatures as a public health priority?\"\nGroups in B: epidemiologists, elderly residents, municipal authorities.\nEpidemiologists study heatwaves and argue about bodies at night: that is a different view.\nElderly residents are the people at risk; they do not say anything.\n\"For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\"\nAnswer: municipal authorities. The trap is the epidemiologists, the experts named in the same paragraph.\n\n- - - - - - - - - - - - - - - - - - - -\n\nTHE PASSAGE: Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 developers: the sedum is \"favoured by developers\". They choose it. The ecologists, named in the same sentence, criticise it.\n2 ecologists: \"Ecologists, for their part, caution that the thin mats ... sustain only a fraction of the insect and bird life\". Saying word: caution.\n3 property owners: \"Owners contend ... that while the wider public enjoys cooler streets, the financial burden falls entirely on them\". Saying word: contend. The wider public gains; it says nothing.\n4 municipalities: \"A number of municipalities have responded with subsidies\". They respond to the owners'' view; they do not hold it.\n5 note: \"Engineers note that a planted roof ... may keep its upper floors comfortable\". Caution belongs to the ecologists; contend to the owners; warn to the planners.\n6 epidemiologists: \"Epidemiologists ... arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat\". Elderly residents are the people at risk, not the speakers.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Identify viewpoint: match a view or action to the group that holds it when other groups are named nearby."}'::jsonb, review_record='{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.2.0"}'::jsonb, content_sha256='a33b3403df07ced31f6fdbddf2601927327d69c4546708a1b8077997c959b008' where code='bh-ielts-targeted-reading-r32-v1' and content_sha256='6146f795b26d85e786766cebb1d0c47c3f52ad2ab480b96660c86fedc765e2c7' and not exists(select 1 from private.ielts_learning_allocations a where a.task_code='bh-ielts-targeted-reading-r32-v1') and not exists(select 1 from private.ielts_learning_content_reviews r where r.task_code='bh-ielts-targeted-reading-r32-v1') and not exists(select 1 from private.ielts_learning_releases x where x.task_code='bh-ielts-targeted-reading-r32-v1');
 if not found then raise exception 'targeted_reading_06_upgrade_blocked: %', 'bh-ielts-targeted-reading-r32-v1'; end if;
 update private.ielts_learning_tasks set version='0.2.0', title='Lesson 6 step 6 of 6: Mixed check', instructions='Read LEARN FIRST and the worked example. Then answer six new questions. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.', success_description='Use the whole routine: TYPE, LOCATE by meaning, PROVE with the exact words, REJECT the trap.', questions='[{"id": "q1", "prompt": "Which paragraph contains a reference to a group that is especially at risk from heat?", "accepted_answers": ["B"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}, {"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}, {"value": "E", "label": "Paragraph E"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q2", "prompt": "Which paragraph contains an explanation of why deeper planting is not always possible?", "accepted_answers": ["D"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}, {"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}, {"value": "E", "label": "Paragraph E"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q3", "prompt": "Heat-absorbing materials such as asphalt release their stored energy only ________ after sunset.", "accepted_answers": ["gradually"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q4", "prompt": "Many older buildings could support deeper planting only after costly ________.", "accepted_answers": ["structural reinforcement"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q5", "prompt": "Which group says that planted roofs can protect the floors closest to them?", "accepted_answers": ["D"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  urban planners"}, {"value": "B", "label": "B  property owners"}, {"value": "C", "label": "C  ecologists"}, {"value": "D", "label": "D  engineers"}, {"value": "E", "label": "E  epidemiologists"}]}, {"id": "q6", "prompt": "Which group says that green roofs should not be treated as a complete answer on their own?", "accepted_answers": ["A"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  urban planners"}, {"value": "B", "label": "B  property owners"}, {"value": "C", "label": "C  ecologists"}, {"value": "D", "label": "D  engineers"}, {"value": "E", "label": "E  epidemiologists"}]}]'::jsonb, content='{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "passage": "LEARN FIRST: use the whole routine on new questions\n\nSix new questions on the same passage. Work on your own and use the four-step routine:\n1. TYPE: what kind of information or word does the question need?\n2. LOCATE: find it by MEANING, not by a word you recognise.\n3. PROVE: point to the exact words in the passage.\n4. REJECT: name the tempting wrong answer and why it is wrong.\n\nWORKED EXAMPLE\n\"Which paragraph contains a reference to a cheaper alternative to green roofs?\"\n1. Type: an option (alternative), and it must be cheaper.\n2. Locate: paragraph F, reflective cool roofs.\n3. Prove: \"are far cheaper on buildings whose structure cannot support soil\".\n4. Reject: E talks about costs (\"costs substantially more\"), but it offers no alternative. Echo word, wrong kind.\nAnswer: F\n\nQuestions 1-2: choose the paragraph, A-F. Questions 3-4: NO MORE THAN TWO WORDS from the passage. Questions 5-6: choose the group.\n\n- - - - - - - - - - - - - - - - - - - -\n\nTHE PASSAGE: Cooling the city from the roof up\n\nA. On windless summer evenings, the core of a large metropolis may remain several degrees warmer than the surrounding countryside, a disparity known as the urban heat island effect. Asphalt, concrete and brick absorb solar radiation throughout the day and surrender it only gradually once the sun has set, while vehicles, air-conditioning units and industrial processes contribute heat of their own. Counter-intuitively, therefore, the contrast between town and country tends to peak not in the early afternoon, when sunlight is most intense, but several hours after dusk.\n\nB. The consequences extend well beyond discomfort. Epidemiologists studying successive heatwaves have linked prolonged night-time warmth to a marked rise in emergency hospital admissions, arguing that bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat; elderly residents of poorly ventilated top-floor apartments appear especially vulnerable. Electricity consumption climbs in parallel as air conditioners run for longer, and the waste heat these machines expel into the street intensifies the very problem they were bought to solve. For municipal authorities, lowering urban temperatures has consequently become as much a public health priority as an energy one.\n\nC. Among the responses that have gained traction is the green roof, in which a layer of growing medium and vegetation is laid over a waterproof membrane. Plants dissipate heat through evapotranspiration: moisture drawn up through the roots evaporates from the leaves, carrying energy away with it. The substrate beneath them also functions as insulation, retarding the passage of heat into the rooms below. Thermal imaging of individual buildings has repeatedly shown planted roofs to be dramatically cooler on hot afternoons than adjacent bitumen surfaces, although readings taken on a single rooftop reveal little about conditions in the surrounding district.\n\nD. The advantages, moreover, are unevenly distributed. Engineers note that a planted roof on a high-rise office block may keep its upper floors comfortable while doing almost nothing for the air at pavement level, where pedestrians actually experience the heat. Ecologists, for their part, caution that the thin mats of drought-tolerant sedum favoured by developers sustain only a fraction of the insect and bird life found in deeper, more varied plantings. Deeper substrate, however, is heavy when saturated, and a considerable proportion of older buildings could not bear the additional load without expensive structural reinforcement.\n\nE. Expense is the objection that property owners raise most persistently. Installation typically costs substantially more than a conventional replacement roof, and irrigation during dry spells, weeding and the inspection of drainage outlets impose recurring costs thereafter. Owners contend, with some justification, that while the wider public enjoys cooler streets, the financial burden falls entirely on them. A number of municipalities have responded with subsidies or reduced stormwater fees, reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers during heavy downpours.\n\nF. Urban planners increasingly regard green roofs as one element of a broader strategy rather than a remedy in themselves. Street trees cast shade precisely where people walk, and reflective ''cool roofs'', which bounce sunlight back rather than absorbing it, are far cheaper on buildings whose structure cannot support soil. Some planners also warn that grants concentrated on prestigious commercial developments risk cooling the districts that need it least. In their view, the question worth asking is not whether green roofs work in general but which combination of measures suits a particular neighbourhood''s buildings, budget and residents.", "teacher_notes": "1 B: \"elderly residents of poorly ventilated top-floor apartments appear especially vulnerable\". Especially at risk = especially vulnerable. Trap D: pedestrians feel the heat but are not said to be at risk.\n2 D: deeper substrate \"is heavy when saturated\" and many older buildings \"could not bear the additional load\". Trap F: it offers cool roofs, an option, not the reason.\n3 gradually (paragraph A): \"surrender it only gradually once the sun has set\". Release = surrender; after sunset = once the sun has set. Trap: ''throughout the day'' is when the heat is absorbed.\n4 structural reinforcement (paragraph D): \"without expensive structural reinforcement\". Costly = expensive. Trap: ''additional load'' is the problem, not the fix.\n5 engineers: \"Engineers note that a planted roof ... may keep its upper floors comfortable\". The floors closest to the roof are the upper floors.\n6 urban planners: they \"regard green roofs as one element of a broader strategy rather than a remedy in themselves\". Not a complete answer = not a remedy in themselves.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Matching information, sentence completion and matching features on one passage, with nearby distractors."}'::jsonb, review_record='{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.2.0"}'::jsonb, content_sha256='803c4565ec6a9f5ed9578d6d742e52c6a74b4316f38711d65fcb4eac8a1cb2bd' where code='bh-ielts-targeted-reading-r33-v1' and content_sha256='713ad5d6360e5918d511c690b9c8c38e7db2df41b4189cad18bf7ec7819ac8dd' and not exists(select 1 from private.ielts_learning_allocations a where a.task_code='bh-ielts-targeted-reading-r33-v1') and not exists(select 1 from private.ielts_learning_content_reviews r where r.task_code='bh-ielts-targeted-reading-r33-v1') and not exists(select 1 from private.ielts_learning_releases x where x.task_code='bh-ielts-targeted-reading-r33-v1');
 if not found then raise exception 'targeted_reading_06_upgrade_blocked: %', 'bh-ielts-targeted-reading-r33-v1'; end if;
end $upgrade$;
